#!/usr/bin/env bash
# Build the Meizu 20 Pro UEFI firmware image (SILICIUM_UEFI.fd).
#
# Uses the uefi-sheng checkout as the EDK II workspace: it already carries the
# Kailua (SM8550) platform package, the Mu base and the Silicium packages.
# The Meizu package lives in Platforms/Meizu/meizu20proPkg and its vendor
# modules in Binaries/meizu20pro (generated by import-meizu-uefi.py).
set -euo pipefail

ROOT=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
UNIXNU_ROOT=${UNIXNU_ROOT:-$ROOT/../unixnu-main-nova}
UEFI_TREE=${UEFI_TREE:-$ROOT/../uefi-sheng-nova}

export WORKSPACE=$UEFI_TREE
export EDK_TOOLS_PATH=$UEFI_TREE/Mu_Basecore/BaseTools
export CONF_PATH=${CONF_PATH:-$ROOT/.cache/uefi-meizu-conf}
export PYTHON_COMMAND=python3
export PACKAGES_PATH="$UEFI_TREE:$UEFI_TREE/Platforms/Meizu:$UNIXNU_ROOT/package:$UNIXNU_ROOT/drivers/DarwinBoot:$UEFI_TREE/Mu_Basecore:$UEFI_TREE/Common/Mu:$UEFI_TREE/Common/Mu_OEM_Sample:$UEFI_TREE/Silicon/Qualcomm:$UEFI_TREE/Silicon/Silicium:$UEFI_TREE/Silicium-ACPI:$UEFI_TREE/Silicium-ACPI/Platforms/Meizu:$UEFI_TREE/Silicium-ACPI/Silicon/Qualcomm"
TOOLCHAIN_PATH=
for PREFIX in /opt/homebrew/opt /usr/local/opt; do
  for PKG in llvm lld; do
    [ -x "$PREFIX/$PKG/bin/llvm-ar" ] && TOOLCHAIN_PATH=$TOOLCHAIN_PATH:$PREFIX/$PKG/bin
    [ -x "$PREFIX/$PKG/bin/ld64.lld" ] && TOOLCHAIN_PATH=$TOOLCHAIN_PATH:$PREFIX/$PKG/bin
  done
done
export PATH=${TOOLCHAIN_PATH#:}:$EDK_TOOLS_PATH/BinWrappers/PosixLike:$EDK_TOOLS_PATH/Source/C/bin:$PATH

for TOOL in clang llvm-ar llvm-lib lld-link ld64.lld; do
  command -v "$TOOL" >/dev/null || { echo "missing toolchain binary: $TOOL" >&2; exit 1; }
done

mkdir -p "$CONF_PATH"
for NAME in target tools_def build_rule; do
  if [ ! -f "$CONF_PATH/$NAME.txt" ]; then
    cp "$EDK_TOOLS_PATH/Conf/$NAME.template" "$CONF_PATH/$NAME.txt"
  fi
done

cd "$WORKSPACE"
exec build -p Platforms/Meizu/meizu20proPkg/meizu20pro.dsc -a AARCH64 -b "${TARGET:-DEBUG}" \
  -t CLANGPDB -n "${JOBS:-8}" -D FD_BASE=0xA7000000 -D FD_SIZE=0x400000 \
  -D FD_BLOCKS=1024 -D ENABLE_SECUREBOOT=1 -D DEVICE_MODEL=meizu20pro \
  -D MEMORY_PROTECTION=TRUE -D SHIP_MODE=FALSE -D BUILDID_STRING=meizu20pro-research
